-- Migration: Year 3 - Psychiatry - Mood Disorders MCQ Bank (1-320)
-- Based on Kaplan & Sadock's Synopsis 12th Ed, First Aid for the Psychiatry Clerkship 5th Ed, and MGH Pocket Psychiatry
-- Date: 2026-04-30

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'mood-disorders' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Major Depressive Disorder (MDD) Basics (1-40)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the minimum duration of symptoms required to diagnose Major Depressive Episode?', '["1 week", "2 weeks", "4 weeks", "6 months"]', 1, 'DSM-5 requires at least 2 weeks of pervasive depressed mood or anhedonia. (Kaplan & Sadock)'),
    (v_topic_id, '2: Which of the following is an essential criterion (must have at least one) for MDD?', '["Insomnia", "Weight loss", "Depressed mood or Anhedonia", "Suicidal ideation"]', 2, 'Must have either depressed mood or loss of interest/pleasure. (First Aid)'),
    (v_topic_id, '3: The "SIGECAPS" mnemonic stands for Sleep, Interest, Guilt, Energy, Concentration, Appetite, Psychomotor, and ____.', '["Sadness", "Suicide", "Sex", "Social withdrawal"]', 1, 'Suicide/suicidal ideation is the last component of SIGECAPS. (First Aid)'),
    (v_topic_id, '4: How many total SIGECAPS symptoms (including depressed mood/anhedonia) are required for an MDD diagnosis?', '["3", "4", "5", "6"]', 2, 'Must have at least 5 of the 9 symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '5: Which sleep abnormality is classically associated with MDD?', '["Increased REM latency", "Decreased REM latency", "No change in REM", "Absence of REM"]', 1, 'MDD features decreased REM latency and increased total REM sleep. (Kaplan & Sadock)'),
    (v_topic_id, '6: A patient with MDD wakes up very early in the morning and cannot go back to sleep. This is called:', '["Terminal insomnia", "Initial insomnia", "Middle insomnia", "Hypersomnia"]', 0, 'Early morning awakening (terminal insomnia) is a classic melancholic feature. (MGH Pocket)'),
    (v_topic_id, '7: What is the lifetime prevalence of MDD in women compared to men?', '["Equal", "Twice as high in women", "Twice as high in men", "Three times as high in men"]', 1, 'Women have approximately a 2:1 ratio compared to men. (Kaplan & Sadock)'),
    (v_topic_id, '8: The presence of which feature rules OUT a diagnosis of Major Depressive Disorder?', '["Psychotic symptoms", "A history of a manic or hypomanic episode", "Anxiety symptoms", "Catatonia"]', 1, 'A manic/hypomanic episode changes the diagnosis to Bipolar Disorder. (DSM-5 / First Aid)'),
    (v_topic_id, '9: "Melancholic features" in MDD are characterized by:', '["Mood reactivity", "Leaden paralysis", "Lack of mood reactivity and profound anhedonia", "Increased appetite"]', 2, 'Mood does not improve even briefly in response to positive events. (Kaplan & Sadock)'),
    (v_topic_id, '10: "Atypical features" in MDD include:', '["Decreased appetite", "Mood reactivity, hypersomnia, hyperphagia, leaden paralysis", "Early morning awakening", "Psychomotor agitation"]', 1, 'Atypical depression classically responds well to MAOIs, though SSRIs are first-line. (First Aid)'),
    (v_topic_id, '11: Which neuroendocrine abnormality is frequently seen in severe MDD?', '["Hypocortisolism", "Hypercortisolism (failure to suppress on dexamethasone test)", "Hypothyroidism", "Hyperprolactinemia"]', 1, 'HPA axis hyperactivity is common in depression. (Kaplan & Sadock)'),
    (v_topic_id, '12: Postpartum onset specifier for MDD requires onset within what timeframe after delivery?', '["1 week", "4 weeks", "6 months", "1 year"]', 1, 'DSM-5 specifies onset within 4 weeks, though clinically up to 1 year is monitored. (First Aid)'),
    (v_topic_id, '13: Seasonal Pattern (SAD) is typically characterized by atypical features and responds to:', '["ECT", "Light therapy", "Lithium", "Antipsychotics"]', 1, 'Light therapy (10,000 lux) is effective for seasonal affective disorder. (MGH Pocket)'),
    (v_topic_id, '14: Which neurotransmitters are primarily implicated in the monoamine hypothesis of depression?', '["GABA and Glutamate", "Serotonin, Norepinephrine, Dopamine", "Acetylcholine and Histamine", "Endorphins"]', 1, 'The core of most antidepressant mechanisms. (Kaplan & Sadock)'),
    (v_topic_id, '15: In older adults, severe depression can present with significant cognitive impairment, mimicking dementia. This is called:', '["Alzheimer''s", "Pseudodementia", "Vascular dementia", "Lewy body dementia"]', 1, 'Patients often say "I don''t know" rather than confabulating. (First Aid)'),
    (v_topic_id, '16: Which is the most common psychiatric comorbidity with MDD?', '["Schizophrenia", "Anxiety Disorders", "Eating Disorders", "Personality Disorders"]', 1, 'High overlap with GAD, Panic Disorder, etc. (Kaplan & Sadock)'),
    (v_topic_id, '17: MDD with psychotic features typically presents with hallucinations/delusions that are:', '["Mood-congruent (e.g., guilt, disease, poverty)", "Mood-incongruent (e.g., alien control)", "Bizarre", "Visual only"]', 0, 'Psychosis in depression is usually related to depressive themes. (First Aid)'),
    (v_topic_id, '18: What is the first-line pharmacological treatment for MDD with psychotic features?', '["SSRI alone", "Antipsychotic alone", "Antidepressant + Antipsychotic (or ECT)", "Lithium"]', 2, 'Combination therapy or ECT is required. (MGH Pocket)'),
    (v_topic_id, '19: Electroconvulsive therapy (ECT) is considered first-line for which presentation of MDD?', '["Mild depression", "Severe depression with food refusal / catatonia / imminent suicide", "Atypical depression", "SAD"]', 1, 'ECT is rapid and life-saving in these situations. (Kaplan & Sadock)'),
    (v_topic_id, '20: What is the most common side effect of ECT?', '["Permanent amnesia", "Retrograde and anterograde amnesia (usually temporary)", "Seizures", "Tardive dyskinesia"]', 1, 'Memory impairment usually resolves within months. (First Aid)'),
    (v_topic_id, '21: Which brain region often shows decreased volume on MRI in patients with chronic MDD?', '["Amygdala", "Hippocampus", "Cerebellum", "Occipital lobe"]', 1, 'Due to prolonged hypercortisolemia and stress. (Kaplan & Sadock)'),
    (v_topic_id, '22: The "Cognitive Triad" of depression (Beck) consists of negative views about:', '["Self, World, Future", "Past, Present, Future", "Family, Friends, Self", "Health, Wealth, Love"]', 0, 'Core concept of Cognitive Behavioral Therapy (CBT). (First Aid)'),
    (v_topic_id, '23: Which psychotherapy is specifically designed to address interpersonal disputes, role transitions, and grief in MDD?', '["CBT", "DBT", "Interpersonal Therapy (IPT)", "Psychodynamic therapy"]', 2, 'Time-limited and highly effective for MDD. (MGH Pocket)'),
    (v_topic_id, '24: A patient has MDD. If they have had one episode, what is the rough probability of having a second episode?', '["10%", "30%", "50-60%", "90%"]', 2, 'Risk increases with each subsequent episode. (Kaplan & Sadock)'),
    (v_topic_id, '25: The term "Double Depression" refers to:', '["MDD + Bipolar", "MDD superimposed on Persistent Depressive Disorder (Dysthymia)", "MDD + Anxiety", "Two episodes of MDD in one year"]', 1, 'Common presentation of chronic low mood with severe dips. (First Aid)'),
    (v_topic_id, '26: Which symptom is most indicative of suicide risk in a depressed patient?', '["Insomnia", "Hopelessness", "Weight gain", "Fatigue"]', 1, 'Hopelessness is the strongest cognitive predictor of suicide. (Kaplan & Sadock)'),
    (v_topic_id, '27: Grief/Bereavement can be distinguished from MDD by:', '["Severity of sadness", "Preservation of self-esteem and focus on the deceased", "Duration > 2 weeks", "Presence of crying"]', 1, 'In MDD, self-esteem is usually low (worthlessness). (DSM-5)'),
    (v_topic_id, '28: Can MDD be diagnosed within the first 2 weeks after the death of a loved one?', '["No, must wait 2 months", "Yes, if criteria are met (DSM-5 removed bereavement exclusion)", "Only if psychotic", "No"]', 1, 'The bereavement exclusion was removed in DSM-5. (First Aid)'),
    (v_topic_id, '29: "Catatonic features" in MDD may include all EXCEPT:', '["Waxy flexibility", "Mutism", "Echolalia", "Hypersexuality"]', 3, 'Hypersexuality is a feature of mania. (MGH Pocket)'),
    (v_topic_id, '30: A depressed patient repeats everything the interviewer says. This catatonic symptom is called:', '["Echopraxia", "Echolalia", "Catalepsy", "Negativism"]', 1, 'Echolalia = repeating words. (Kaplan & Sadock)'),
    (v_topic_id, '31: Treatment of choice for MDD with catatonic features?', '["Lorazepam (or ECT if unresponsive)", "Haloperidol", "Fluoxetine", "Lithium"]', 0, 'Benzodiazepines or ECT are first-line for catatonia. (MGH Pocket)'),
    (v_topic_id, '32: "Anxious distress" specifier in MDD requires how many anxiety symptoms?', '["At least 2", "At least 5", "All of them", "None"]', 0, 'Indicates higher risk of suicide and poorer response to treatment. (DSM-5)'),
    (v_topic_id, '33: "Mixed features" specifier in MDD implies:', '["Subthreshold manic/hypomanic symptoms during the depressive episode", "Anxiety and depression", "Psychosis and depression", "None of the above"]', 0, 'Increases risk of transition to Bipolar Disorder. (DSM-5)'),
    (v_topic_id, '34: In children, MDD can frequently present as:', '["Euphoria", "Irritability rather than depressed mood", "Hyperactivity", "Mutism"]', 1, 'Irritability is a very common mood equivalent in youth. (First Aid)'),
    (v_topic_id, '35: Masked depression refers to MDD presenting primarily with:', '["Somatic/physical complaints", "Psychosis", "Mania", "Anxiety"]', 0, 'Common in certain cultures and the elderly. (Kaplan & Sadock)'),
    (v_topic_id, '36: What percentage of MDD patients eventually die by suicide?', '["1%", "5-15%", "30%", "50%"]', 1, 'A significantly elevated risk compared to the general population. (First Aid)'),
    (v_topic_id, '37: The most robust risk factor for completed suicide is:', '["Family history", "Prior suicide attempt", "Female gender", "Substance abuse"]', 1, 'Past attempts are the strongest predictor. (Kaplan & Sadock)'),
    (v_topic_id, '38: Who has the highest rate of completed suicide in the US?', '["Young black females", "Middle-aged hispanic males", "Elderly white males", "Teenage boys"]', 2, 'Often via firearms. (First Aid)'),
    (v_topic_id, '39: Protective factors against suicide include all EXCEPT:', '["Marriage", "Pregnancy", "Religious beliefs", "Recent job loss"]', 3, 'Job loss is a stressor/risk factor. (Kaplan & Sadock)'),
    (v_topic_id, '40: When assessing suicide, "SLAP" stands for Specificity, Lethality, Availability, and ____.', '["Proximity", "Prognosis", "Preventability", "Psychosis"]', 0, 'Assessing the plan''s proximity of help. (MGH Pocket)'),

    -- SECTION 2: Persistent Depressive Disorder & PMDD (41-70)
    (v_topic_id, '41: Persistent Depressive Disorder (Dysthymia) requires depressed mood for at least how long in adults?', '["6 months", "1 year", "2 years", "5 years"]', 2, 'Must be present more days than not for 2 years. (DSM-5)'),
    (v_topic_id, '42: In children and adolescents, the duration requirement for PDD (Dysthymia) is:', '["6 months", "1 year", "2 years", "3 years"]', 1, 'Shorter duration required for pediatric diagnosis. (First Aid)'),
    (v_topic_id, '43: During the 2-year period of PDD, the patient cannot be without symptoms for more than:', '["1 week", "1 month", "2 months", "6 months"]', 2, 'A gap of >2 months breaks the timeline. (DSM-5)'),
    (v_topic_id, '44: How many additional symptoms (like poor appetite, insomnia, low energy, low self-esteem, poor concentration, hopelessness) are required for PDD?', '["1", "2", "4", "5"]', 1, 'Requires depressed mood + at least 2 other symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '45: If a patient meets criteria for MDD continuously for 2 years, what is the diagnosis?', '["MDD only", "PDD (with persistent major depressive episode)", "Bipolar", "Cyclothymia"]', 1, 'DSM-5 consolidated chronic MDD and Dysthymia into PDD. (First Aid)'),
    (v_topic_id, '46: Premenstrual Dysphoric Disorder (PMDD) symptoms must occur during which phase of the menstrual cycle?', '["Follicular phase", "Luteal phase (week before menses)", "During menses only", "Ovulation"]', 1, 'Symptoms improve shortly after the onset of menses. (MGH Pocket)'),
    (v_topic_id, '47: First-line pharmacological treatment for PMDD?', '["Lithium", "SSRIs (either continuous or luteal-phase only)", "Antipsychotics", "Benzodiazepines"]', 1, 'Fluoxetine or Sertraline are commonly used. (First Aid)'),
    (v_topic_id, '48: Disruptive Mood Dysregulation Disorder (DMDD) was introduced in DSM-5 to reduce the overdiagnosis of:', '["ADHD", "Pediatric Bipolar Disorder", "Autism", "Conduct Disorder"]', 1, 'Characterized by severe recurrent temper outbursts out of proportion to the situation. (Kaplan & Sadock)'),
    (v_topic_id, '49: DMDD cannot be diagnosed for the first time before age ___ or after age ___.', '["3; 10", "6; 18", "10; 21", "12; 25"]', 1, 'Onset must be before age 10, diagnosed between 6-18. (DSM-5)'),
    (v_topic_id, '50: A patient has chronic mild depression for 3 years, but recently had a 2-week period of severe depression. Diagnosis?', '["Cyclothymia", "Persistent Depressive Disorder with intermittent major depressive episodes", "Bipolar II", "Normal mourning"]', 1, 'Also known historically as Double Depression. (First Aid)'),
    (v_topic_id, '51: Which personality disorder is highly comorbid with PDD?', '["Borderline PD", "Antisocial PD", "Schizoid PD", "Avoidant PD"]', 0, 'High overlap with Cluster B/C traits. (Kaplan & Sadock)'),
    (v_topic_id, '52: What is the recommended treatment for Persistent Depressive Disorder?', '["Psychotherapy alone", "Antidepressants alone", "Combination of Psychotherapy and Antidepressants", "ECT"]', 2, 'Combination yields the best long-term results. (MGH Pocket)'),
    (v_topic_id, '53: PMDD differs from Premenstrual Syndrome (PMS) primarily in:', '["Physical symptoms", "Severity of affective symptoms and functional impairment", "Timing", "Duration"]', 1, 'PMDD is essentially severe, debilitating PMS. (Kaplan & Sadock)'),
    (v_topic_id, '54: Which physical symptom is NOT part of the PMDD criteria?', '["Breast tenderness", "Joint/muscle pain", "Bloating", "Fever"]', 3, 'Fever is not a criteria. (DSM-5)'),
    (v_topic_id, '55: PMDD requires at least how many total symptoms present in the final week before menses?', '["2", "3", "5", "7"]', 2, 'Must include at least one core affective symptom. (First Aid)'),
    (v_topic_id, '56: A diary of symptoms for PMDD must confirm the cyclical nature for at least how many symptomatic cycles?', '["1", "2", "6", "12"]', 1, 'Prospective daily ratings for at least 2 cycles. (DSM-5)'),
    (v_topic_id, '57: Substance/Medication-Induced Depressive Disorder requires that symptoms:', '["Developed during or soon after substance intoxication/withdrawal", "Preceded the substance use", "Persist for years after stopping", "None of the above"]', 0, 'Direct physiological consequence. (First Aid)'),
    (v_topic_id, '58: Which medication is notoriously associated with inducing depression?', '["Penicillin", "Interferon-alpha", "Vitamin C", "Aspirin"]', 1, 'Also isotretinoin, beta-blockers, corticosteroids. (MGH Pocket)'),
    (v_topic_id, '59: Which recreational drug withdrawal commonly mimics severe depression and hypersomnia?', '["Alcohol", "Cocaine/Amphetamines (Stimulant crash)", "Heroin", "Cannabis"]', 1, 'Stimulant withdrawal features severe dysphoria and "crashing". (Kaplan & Sadock)'),
    (v_topic_id, '60: Depressive disorder due to another medical condition is common with which neurological disease?', '["ALS", "Parkinson''s Disease", "Myasthenia Gravis", "Guillain-Barre"]', 1, 'Very high prevalence in PD, Stroke, and MS. (First Aid)'),
    (v_topic_id, '61: Left frontal hemisphere strokes are famously associated with:', '["Mania", "Depression", "Psychosis", "Apathy"]', 1, 'Left frontal strokes often cause depression. (Kaplan & Sadock)'),
    (v_topic_id, '62: Right frontal hemisphere strokes are classically associated with:', '["Depression", "Mania / Euphoria", "Blindness", "Deafness"]', 1, 'Right = Mania/indifference. (MGH Pocket)'),
    (v_topic_id, '63: Pancreatic cancer can present initially with which psychiatric syndrome?', '["Mania", "Depression", "Panic attacks", "OCD"]', 1, 'Major depression can precede physical symptoms in pancreatic cancer. (First Aid)'),
    (v_topic_id, '64: Hypothyroidism mimics depression. Which lab test is essential in a depression workup?', '["TSH", "LFTs", "Amylase", "Troponin"]', 0, 'TSH should be checked to rule out hypothyroidism. (MGH Pocket)'),
    (v_topic_id, '65: Which vitamin deficiency can cause depressive symptoms?', '["Vitamin A", "Vitamin B12 and Folate", "Vitamin C", "Vitamin K"]', 1, 'Often checked in initial workup. (Kaplan & Sadock)'),
    (v_topic_id, '66: DMDD core feature is severe temper outbursts occurring at least how many times per week?', '["1", "3 or more", "7", "Daily"]', 1, 'Occurs on average 3+ times a week. (DSM-5)'),
    (v_topic_id, '67: In DMDD, the mood between temper outbursts must be:', '["Normal", "Persistently irritable or angry most of the day", "Euphoric", "Anxious"]', 1, 'Irritable/angry mood must be observable by others. (First Aid)'),
    (v_topic_id, '68: If a child meets criteria for both DMDD and Oppositional Defiant Disorder (ODD), what is the diagnosis?', '["ODD only", "DMDD only", "Both", "Bipolar"]', 1, 'DMDD trumps ODD. (DSM-5)'),
    (v_topic_id, '69: The "Dexamethasone Suppression Test" in MDD typically shows:', '["Complete suppression of cortisol", "Non-suppression (cortisol remains high)", "Low baseline cortisol", "None of the above"]', 1, 'Reflects HPA axis dysregulation. (Kaplan & Sadock)'),
    (v_topic_id, '70: Which rating scale is clinically used to monitor depression severity by a clinician?', '["PHQ-9", "HAM-D (Hamilton Depression Rating Scale)", "BDI (Beck Depression Inventory)", "MMSE"]', 1, 'HAM-D is clinician-administered; PHQ-9 and BDI are self-rated. (MGH Pocket)'),

    -- SECTION 3: Bipolar I Disorder (71-110)
    (v_topic_id, '71: What is the defining feature of Bipolar I Disorder?', '["At least one major depressive episode", "At least one manic episode", "Hypomania and depression", "Cyclical moods"]', 1, 'A single manic episode is sufficient for a Bipolar I diagnosis. (DSM-5)'),
    (v_topic_id, '72: What is the minimum duration for a manic episode (unless hospitalized)?', '["1 day", "4 days", "1 week", "2 weeks"]', 2, 'Must last at least 1 week, or any duration if hospitalization is required. (First Aid)'),
    (v_topic_id, '73: To diagnose mania, the patient must have abnormally elevated, expansive, or irritable mood AND increased energy, plus how many other symptoms?', '["1 (2 if irritable)", "3 (4 if mood is only irritable)", "5", "7"]', 1, 'DIGFAST criteria. (Kaplan & Sadock)'),
    (v_topic_id, '74: The "DIGFAST" mnemonic stands for Distractibility, Insomnia, Grandiosity, Flight of ideas, Activity increase, Speech (pressured), and ____.', '["Sadness", "Thoughtlessness (risky behavior)", "Tics", "Tremors"]', 1, 'Thoughtless/reckless behaviors (e.g., spending sprees, sexual indiscretions). (First Aid)'),
    (v_topic_id, '75: A patient sleeps 2 hours a night but feels completely energized. This is termed:', '["Insomnia", "Decreased need for sleep", "Hypersomnia", "Narcolepsy"]', 1, 'Classic hallmark of mania. (MGH Pocket)'),
    (v_topic_id, '76: Is Major Depressive Episode REQUIRED for a diagnosis of Bipolar I?', '["Yes", "No", "Only in women", "Only in children"]', 1, 'Only a manic episode is required, though most patients eventually experience depression. (First Aid)'),
    (v_topic_id, '77: Can psychotic features (delusions/hallucinations) be present in mania?', '["Yes, and they are common", "No, that makes it Schizophrenia", "Only if drug-induced", "No"]', 0, 'Psychotic features can occur in severe mania. (Kaplan & Sadock)'),
    (v_topic_id, '78: If a patient has a manic episode triggered by an antidepressant medication, and it persists after the drug is stopped, the diagnosis is:', '["Medication-induced mania", "Bipolar I Disorder", "MDD", "Schizoaffective"]', 1, 'DSM-5 considers a full manic episode emerging during antidepressant treatment and persisting beyond the physiological effect as Bipolar I. (DSM-5)'),
    (v_topic_id, '79: Rapid Cycling Bipolar Disorder is defined as having at least how many mood episodes per year?', '["2", "4", "6", "12"]', 1, '4 or more episodes in 12 months. (First Aid)'),
    (v_topic_id, '80: Which medication is notoriously poor at treating rapid cycling bipolar and may worsen it?', '["Valproate", "Antidepressants", "Lamotrigine", "Atypical antipsychotics"]', 1, 'Antidepressants can accelerate cycling. (MGH Pocket)'),
    (v_topic_id, '81: First-line maintenance treatment for Bipolar I Disorder?', '["Haloperidol", "Lithium, Valproate, or Quetiapine", "Sertraline", "Venlafaxine"]', 1, 'Mood stabilizers or atypical antipsychotics are first-line. (Kaplan & Sadock)'),
    (v_topic_id, '82: Which medication is proven to decrease suicide risk in Bipolar Disorder?', '["Valproate", "Carbamazepine", "Lithium", "Olanzapine"]', 2, 'Lithium has a unique anti-suicidal property. (First Aid)'),
    (v_topic_id, '83: A manic patient presents with severe agitation. First-line acute treatment usually includes:', '["Lithium alone", "Antipsychotic (e.g., Haloperidol or Olanzapine) +/- Benzodiazepine", "SSRI", "Valproate alone"]', 1, 'Antipsychotics act faster than mood stabilizers for acute agitation. (MGH Pocket)'),
    (v_topic_id, '84: What is the lifetime prevalence of Bipolar I Disorder?', '["1%", "5%", "10%", "20%"]', 0, 'Approximately 1% of the population. (Kaplan & Sadock)'),
    (v_topic_id, '85: The gender ratio (Male:Female) for Bipolar I Disorder is:', '["2:1", "1:2", "1:1", "3:1"]', 2, 'Equally common in men and women (unlike MDD). (First Aid)'),
    (v_topic_id, '86: Men with Bipolar I tend to have more ____ episodes, while women tend to have more ____ episodes.', '["Manic; Depressive", "Depressive; Manic", "Mixed; Manic", "None"]', 0, 'Women also have a higher rate of rapid cycling. (Kaplan & Sadock)'),
    (v_topic_id, '87: Bipolar I has a very strong genetic component. If one identical twin has Bipolar I, the concordance rate for the other twin is roughly:', '["10%", "30%", "70-80%", "100%"]', 2, 'Highest genetic loading among major psychiatric disorders. (First Aid)'),
    (v_topic_id, '88: Which neuroanatomic finding is sometimes associated with Bipolar Disorder?', '["Enlarged ventricles", "Shrunken cerebellum", "Enlarged amygdala", "Loss of substantia nigra"]', 0, 'Similar to schizophrenia, some ventricular enlargement can be seen. (Kaplan & Sadock)'),
    (v_topic_id, '89: Acute mania treatment in a pregnant patient (first trimester)?', '["Valproate", "Lithium", "Haloperidol or ECT", "Carbamazepine"]', 2, 'High-potency typicals like Haldol or ECT are safest. Lithium has Ebstein''s risk. Valproate causes neural tube defects. (MGH Pocket)'),
    (v_topic_id, '90: Bipolar Disorder commonly has a high comorbidity with:', '["OCD", "Substance Use Disorders", "Anorexia", "Schizoid PD"]', 1, 'Over 50% lifetime prevalence of substance abuse. (First Aid)'),
    (v_topic_id, '91: "Flight of ideas" refers to:', '["Forgetting thoughts", "Rapid, continuous speech with sudden topic changes based on understandable associations", "Word salad", "Echolalia"]', 1, 'Connections are logical but very fast. (Kaplan & Sadock)'),
    (v_topic_id, '92: "Pressured speech" in mania is characterized by:', '["Slow, deliberate speech", "Loud, rapid, non-interruptible speech", "Whispering", "Mute"]', 1, 'Patient feels a compulsion to speak. (MGH Pocket)'),
    (v_topic_id, '93: What is "Grandiosity"?', '["Feeling worthless", "Inflated self-esteem or delusional belief of having special powers/wealth", "Seeing ghosts", "None of the above"]', 1, 'Core feature of mania. (First Aid)'),
    (v_topic_id, '94: Which condition must be ruled out before diagnosing Bipolar I in a young adult?', '["Hyperthyroidism", "Substance intoxication (e.g., cocaine, meth)", "CNS tumor", "All of the above"]', 3, 'Always rule out medical/substance causes of mania. (DSM-5)'),
    (v_topic_id, '95: A patient has a manic episode but insight is preserved and they are not hospitalized. Can they be diagnosed with Bipolar I?', '["Yes, if it lasts > 1 week and meets criteria", "No, must lack insight", "No, must be hospitalized", "No"]', 0, 'Hospitalization is not required if duration and symptom criteria are met, though mania often leads to it. (First Aid)'),
    (v_topic_id, '96: "Mixed Features" specifier in Bipolar I means:', '["Mania and depression happening at different times", "Full manic episode with at least 3 depressive symptoms present simultaneously", "Anxiety and mania", "None"]', 1, 'High risk for suicide due to high energy + low mood. (DSM-5)'),
    (v_topic_id, '97: Untreated, a typical manic episode lasts roughly:', '["1 week", "3 months", "1 year", "5 years"]', 1, 'Usually lasts a few months if untreated. (Kaplan & Sadock)'),
    (v_topic_id, '98: In Bipolar I, depressive episodes are typically ____ than manic episodes.', '["Shorter and less frequent", "Longer and more frequent", "Equal in duration", "None of the above"]', 1, 'Patients spend much more time depressed than manic. (First Aid)'),
    (v_topic_id, '99: Bipolar depression differs clinically from Unipolar depression (MDD) by having higher rates of:', '["Insomnia", "Atypical features (hypersomnia, hyperphagia) and psychomotor retardation", "Weight loss", "Agitation"]', 1, 'Bipolar depression often looks "atypical". (MGH Pocket)'),
    (v_topic_id, '100: Which antidepressant class is most likely to induce a manic switch in a bipolar patient?', '["SSRIs", "TCAs and SNRIs", "Bupropion", "Mirtazapine"]', 1, 'Dual-action antidepressants have a higher switch rate. (Kaplan & Sadock)'),
    (v_topic_id, '101: If an antidepressant MUST be used in Bipolar Disorder, it should ALWAYS be paired with:', '["A mood stabilizer or antipsychotic", "A benzodiazepine", "A stimulant", "Nothing"]', 0, 'To prevent manic switch. (First Aid)'),
    (v_topic_id, '102: What is the risk of a manic switch if an SSRI is given WITHOUT a mood stabilizer?', '["< 1%", "10-15%", "50%", "100%"]', 1, 'Significant risk, hence antidepressants are avoided as monotherapy. (MGH Pocket)'),
    (v_topic_id, '103: A patient on Lithium presents with tremor, ataxia, vomiting, and confusion. Diagnosis?', '["Mania", "Lithium Toxicity", "Serotonin Syndrome", "NMS"]', 1, 'Medical emergency requiring possible dialysis. (First Aid)'),
    (v_topic_id, '104: Which medication is contraindicated with Lithium as it can acutely raise Lithium levels?', '["Aspirin", "NSAIDs (e.g., Ibuprofen) and Thiazide diuretics", "Acetaminophen", "Beta blockers"]', 1, 'Thiazides, NSAIDs, and ACE inhibitors decrease Li clearance. (MGH Pocket)'),
    (v_topic_id, '105: Valproate (Depakote) is particularly effective for which type of Bipolar Disorder?', '["Pure mania", "Rapid cycling and Mixed episodes", "Depressive episodes", "None"]', 1, 'Often preferred over Lithium for mixed/rapid cycling. (Kaplan & Sadock)'),
    (v_topic_id, '106: Major teratogenic risk of Valproate?', '["Ebstein anomaly", "Neural tube defects (Spina Bifida)", "Cleft palate", "Phocomelia"]', 1, 'Must supplement with high-dose folate if unavoidable, but generally contraindicated in pregnancy. (First Aid)'),
    (v_topic_id, '107: Carbamazepine can cause which serious idiosyncratic adverse effect?', '["Renal failure", "Stevens-Johnson Syndrome and Agranulocytosis", "Pulmonary fibrosis", "Cataracts"]', 1, 'Requires monitoring of CBC and HLA-B*1502 screening in Asians. (MGH Pocket)'),
    (v_topic_id, '108: Which atypical antipsychotic is FDA-approved specifically for Bipolar Depression?', '["Haloperidol", "Lurasidone and Quetiapine", "Risperidone", "Ziprasidone"]', 1, 'Also Olanzapine-Fluoxetine combination (Symbyax). (First Aid)'),
    (v_topic_id, '109: Lamotrigine is used in Bipolar Disorder primarily for:', '["Acute mania", "Maintenance and prevention of Bipolar Depression", "Rapid cycling", "Psychosis"]', 1, 'Not effective for acute mania. (Kaplan & Sadock)'),
    (v_topic_id, '110: What is the black box warning for Lamotrigine?', '["Hepatotoxicity", "Stevens-Johnson Syndrome (SJS) / Toxic Epidermal Necrolysis", "Agranulocytosis", "Seizures"]', 1, 'Must be titrated very slowly to reduce risk. (MGH Pocket)'),

    -- SECTION 4: Bipolar II and Cyclothymia (111-150)
    (v_topic_id, '111: Bipolar II Disorder requires the presence of:', '["At least one manic episode", "At least one hypomanic episode AND at least one major depressive episode", "Only hypomanic episodes", "Cyclic mood swings without MDD"]', 1, 'No history of full mania allowed. (DSM-5)'),
    (v_topic_id, '112: What is the duration requirement for a Hypomanic Episode?', '["1 day", "At least 4 consecutive days", "1 week", "2 weeks"]', 1, 'Shorter than mania (which is 1 week). (First Aid)'),
    (v_topic_id, '113: Which of the following distinguishes Hypomania from Mania?', '["Hypomania requires hospitalization", "Hypomania has psychotic features", "Hypomania does NOT cause marked impairment in social/occupational functioning", "Hypomania lasts longer"]', 2, 'If it causes marked impairment, requires hospitalization, or has psychosis = Mania. (DSM-5)'),
    (v_topic_id, '114: A patient has a 5-day episode of elevated mood, decreased sleep, and rapid speech, but continues working and has no delusions. Diagnosis?', '["Mania", "Hypomania", "Normal", "Schizoaffective"]', 1, 'Classic hypomania. (Kaplan & Sadock)'),
    (v_topic_id, '115: If a patient with Bipolar II develops a full Manic Episode, what happens to their diagnosis?', '["Stays Bipolar II", "Changes to Bipolar I", "Changes to Cyclothymia", "Changes to Schizoaffective"]', 1, 'A single manic episode upgrades the diagnosis to Bipolar I. (First Aid)'),
    (v_topic_id, '116: Which is generally more chronic and presents with more depressive morbidity: Bipolar I or Bipolar II?', '["Bipolar I", "Bipolar II", "Equal", "Neither"]', 1, 'Bipolar II patients spend more time in depressive episodes. (MGH Pocket)'),
    (v_topic_id, '117: Suicide risk in Bipolar II compared to Bipolar I is:', '["Much lower", "Similar or potentially higher due to severe chronic depression", "Zero", "Twice as high"]', 1, 'High lethality in Bipolar II depression. (Kaplan & Sadock)'),
    (v_topic_id, '118: Cyclothymic Disorder requires alternating periods of hypomanic symptoms and depressive symptoms for at least:', '["6 months", "1 year", "2 years", "5 years"]', 2, '2 years in adults, 1 year in children/adolescents. (DSM-5)'),
    (v_topic_id, '119: In Cyclothymia, do the depressive symptoms ever meet full criteria for a Major Depressive Episode?', '["Yes, frequently", "No, they are subthreshold", "Yes, but only once", "Always"]', 1, 'If they meet criteria for MDD, the diagnosis becomes Bipolar II. (First Aid)'),
    (v_topic_id, '120: In Cyclothymia, the patient cannot be symptom-free for more than:', '["1 month", "2 months", "6 months", "1 year"]', 1, 'Must be symptomatic at least half the time, no gap >2 months. (DSM-5)'),
    (v_topic_id, '121: Roughly what percentage of patients with Cyclothymia will eventually develop Bipolar I or II?', '["1%", "15-50%", "90%", "100%"]', 1, 'High rate of conversion to full bipolar disorder. (Kaplan & Sadock)'),
    (v_topic_id, '122: First-line treatment for Bipolar II depression?', '["Sertraline", "Quetiapine or Lurasidone", "Haloperidol", "Venlafaxine"]', 1, 'Similar to Bipolar I depression; avoid SSRI monotherapy. (MGH Pocket)'),
    (v_topic_id, '123: First-line treatment for Cyclothymia?', '["Mood stabilizers (Lithium, Valproate)", "SSRIs", "Stimulants", "No medication, only CBT"]', 0, 'Mood stabilizers are typically used if medication is required. (First Aid)'),
    (v_topic_id, '124: Can Bipolar II have psychotic features during the depressive episode?', '["Yes", "No", "Only visual", "Only tactile"]', 0, 'Yes, psychosis can occur in the depressive episode of BP II. (If psychosis occurs during hypomania, it becomes mania and thus BP I). (DSM-5)'),
    (v_topic_id, '125: Bipolar disorder in children is often confused with which childhood disorder?', '["Autism", "ADHD", "Oppositional Defiant Disorder", "Tourette''s"]', 1, 'Due to shared symptoms like distractibility, hyperactivity, and impulsivity. (Kaplan & Sadock)'),
    (v_topic_id, '126: A key distinguishing feature between ADHD and pediatric Bipolar Disorder is:', '["Hyperactivity", "Episodic nature of symptoms and presence of grandiosity/euphoria in Bipolar", "Inattention", "School failure"]', 1, 'ADHD is chronic and non-episodic; Bipolar has distinct episodes. (First Aid)'),
    (v_topic_id, '127: Which of the following is a common trigger for a manic or hypomanic episode?', '["Sleep deprivation", "Eating too much sugar", "Exercise", "Watching TV"]', 0, 'Jet lag, night shifts, and sleep deprivation strongly trigger mania. (MGH Pocket)'),
    (v_topic_id, '128: Schizoaffective Disorder differs from Bipolar Disorder with psychotic features because:', '["Schizoaffective has no mood episodes", "In Schizoaffective, psychosis must be present for >2 weeks IN THE ABSENCE of a major mood episode", "Bipolar has no psychosis", "None of the above"]', 1, 'Crucial distinction for board exams. (DSM-5 / First Aid)'),
    (v_topic_id, '129: If a patient has delusions and hallucinations ONLY during their manic episodes, the diagnosis is:', '["Schizoaffective Disorder", "Bipolar I Disorder with psychotic features", "Schizophrenia", "MDD"]', 1, 'Psychosis is mood-congruent or at least concurrent with mood. (Kaplan & Sadock)'),
    (v_topic_id, '130: Does Bipolar II disorder occur more in men or women?', '["Men", "Women", "Equal", "Only in children"]', 1, 'Unlike BP I (equal), BP II is slightly more common in women. (First Aid)'),
    (v_topic_id, '131: A 25-year-old postpartum female presents with severe insomnia, agitation, and delusions about her baby being a demon, 1 week after delivery. Diagnosis?', '["Postpartum Depression", "Postpartum Psychosis (usually a manifestation of Bipolar Disorder)", "Schizophrenia", "Normal baby blues"]', 1, 'Postpartum psychosis is a psychiatric emergency highly linked to Bipolar Disorder. (MGH Pocket)'),
    (v_topic_id, '132: Treatment for Postpartum Psychosis?', '["Hospitalization and Antipsychotics/Mood stabilizers", "Send home with reassurance", "SSRIs", "CBT"]', 0, 'High risk of infanticide and suicide. (First Aid)'),
    (v_topic_id, '133: Normal "Postpartum Blues" lasts for how long?', '["Up to 2 weeks", "2 months", "6 months", "1 year"]', 0, 'Self-resolving by day 14. If >2 weeks, evaluate for depression. (Kaplan & Sadock)'),
    (v_topic_id, '134: Postpartum Blues occurs in what percentage of women?', '["5%", "15%", "50-85%", "100%"]', 2, 'Very common, due to hormonal shifts. (First Aid)'),
    (v_topic_id, '135: What is "Euthymia"?', '["A type of mania", "Normal, tranquil mood", "Severe depression", "Psychosis"]', 1, 'The goal of treatment in mood disorders. (MGH Pocket)'),
    (v_topic_id, '136: A patient with Bipolar II is on a mood stabilizer but remains severely depressed. What is a reasonable next step?', '["Stop the mood stabilizer", "Add an antidepressant carefully or switch to an atypical like Quetiapine/Lurasidone", "Add a stimulant", "Give Haloperidol"]', 1, 'Must treat the depression without triggering hypomania. (Kaplan & Sadock)'),
    (v_topic_id, '137: Which medical condition can classically cause secondary mania?', '["Hypothyroidism", "Hyperthyroidism", "Diabetes", "Hypertension"]', 1, 'Thyrotoxicosis can mimic mania. (First Aid)'),
    (v_topic_id, '138: Multiple Sclerosis is associated with which mood changes?', '["Only depression", "Only mania", "Depression and sometimes euphoria/mania", "No mood changes"]', 2, 'High rate of mood lability. (Kaplan & Sadock)'),
    (v_topic_id, '139: High-dose corticosteroids (e.g., Prednisone) can induce:', '["Mania, Depression, or Psychosis", "Only sleepiness", "Only hunger", "Nothing"]', 0, 'Steroid-induced psychosis/mania is well documented. (MGH Pocket)'),
    (v_topic_id, '140: Tertiary syphilis (General Paresis) can present with:', '["Mania and grandiosity", "OCD", "Phobias", "Panic disorder"]', 0, 'Classic organic cause of grandiosity. (First Aid)'),
    (v_topic_id, '141: Wilson''s disease can present with mood lability and is associated with which physical finding?', '["Kayser-Fleischer rings", "Blue sclera", "Janeway lesions", "Osler nodes"]', 0, 'Copper deposition in brain and cornea. (Kaplan & Sadock)'),
    (v_topic_id, '142: Huntington''s disease often presents with which psychiatric symptom years before the chorea?', '["Schizophrenia", "Depression and irritability", "Panic attacks", "Autism"]', 1, 'High suicide rate in Huntington''s. (First Aid)'),
    (v_topic_id, '143: A "hypomanic" episode by definition does NOT cause:', '["Decreased need for sleep", "Talkativeness", "Marked impairment in functioning", "Increased goal-directed activity"]', 2, 'If it causes marked impairment, it is mania. (DSM-5)'),
    (v_topic_id, '144: Can Bipolar II patients have hospitalizations?', '["No, never", "Yes, but only for depressive episodes", "Yes, for hypomania", "Yes, for both"]', 1, 'Hospitalization for hypomania makes it mania (thus BP I). They can be hospitalized for severe depression. (MGH Pocket)'),
    (v_topic_id, '145: Which drug of abuse is most likely to cause a syndrome indistinguishable from acute mania?', '["Heroin", "Cocaine / Amphetamines", "Benzodiazepines", "Alcohol"]', 1, 'Stimulant intoxication mimics mania perfectly. (First Aid)'),
    (v_topic_id, '146: What distinguishes stimulant intoxication from primary mania?', '["Presence of delusions", "Urine toxicology screen and shorter duration (hours to days)", "Pressured speech", "Insomnia"]', 1, 'Symptoms clear as the drug is metabolized. (Kaplan & Sadock)'),
    (v_topic_id, '147: Maintenance therapy for Cyclothymia is most similar to maintenance for:', '["MDD", "Bipolar Disorder", "Schizophrenia", "Anxiety"]', 1, 'Mood stabilizers are the core. (MGH Pocket)'),
    (v_topic_id, '148: A patient is taking an MAOI for atypical depression. They eat aged cheese. What happens?', '["Serotonin syndrome", "Hypertensive crisis", "Neuroleptic Malignant Syndrome", "Seizure"]', 1, 'Tyramine accumulation causes massive norepinephrine release. (First Aid)'),
    (v_topic_id, '149: Treatment for MAOI-induced hypertensive crisis?', '["Propranolol", "Phentolamine (alpha blocker)", "Flumazenil", "Naloxone"]', 1, 'Must block alpha receptors. (Kaplan & Sadock)'),
    (v_topic_id, '150: Patient on Fluoxetine is switched to Tranylcypromine (MAOI). How long must they wait?', '["1 week", "2 weeks", "5 weeks", "No wait"]', 2, 'Fluoxetine has a very long half-life. Other SSRIs require 2 weeks. (MGH Pocket)'),

    -- SECTION 5: Psychopharmacology of Mood Disorders (151-200)
    (v_topic_id, '151: SSRIs work by inhibiting the reuptake of Serotonin at the:', '["Postsynaptic neuron", "Presynaptic cleft", "Dendrite", "Axon hillock"]', 1, 'Increases Serotonin in the synaptic cleft. (Kaplan & Sadock)'),
    (v_topic_id, '152: Which SSRI has the longest half-life?', '["Sertraline", "Paroxetine", "Fluoxetine", "Citalopram"]', 2, 'Has active metabolite norfluoxetine; auto-tapers. (First Aid)'),
    (v_topic_id, '153: Which SSRI is notoriously known for causing the most weight gain and sedation, and having a short half-life (high withdrawal risk)?', '["Fluoxetine", "Sertraline", "Paroxetine", "Escitalopram"]', 2, 'Also has mild anticholinergic effects. (MGH Pocket)'),
    (v_topic_id, '154: Which SSRI has a dose-dependent risk of QTc prolongation?', '["Citalopram", "Paroxetine", "Fluvoxamine", "Sertraline"]', 0, 'FDA warns against doses >40mg/day (or >20mg in elderly). (First Aid)'),
    (v_topic_id, '155: Common side effects of SSRIs include all EXCEPT:', '["GI upset", "Sexual dysfunction", "Insomnia/Restlessness", "Hypertensive crisis"]', 3, 'Hypertensive crisis is MAOI. (Kaplan & Sadock)'),
    (v_topic_id, '156: SNRIs (like Venlafaxine and Duloxetine) block reuptake of Serotonin and ____.', '["Dopamine", "Norepinephrine", "Histamine", "GABA"]', 1, 'Dual reuptake inhibitors. (First Aid)'),
    (v_topic_id, '157: Venlafaxine has a specific side effect at high doses due to its NE effects. What is it?', '["Hypotension", "Hypertension", "Bradycardia", "Asthma"]', 1, 'Must monitor blood pressure. (MGH Pocket)'),
    (v_topic_id, '158: Duloxetine is commonly used for depression with comorbid:', '["Neuropathic pain or Fibromyalgia", "Schizophrenia", "Bipolar mania", "Seizures"]', 0, 'FDA approved for diabetic peripheral neuropathy. (First Aid)'),
    (v_topic_id, '159: Bupropion works by inhibiting reuptake of:', '["Serotonin", "Norepinephrine and Dopamine", "GABA", "Glutamate"]', 1, 'NDRI. Lacks serotonin side effects. (Kaplan & Sadock)'),
    (v_topic_id, '160: What are the two major benefits of Bupropion over SSRIs?', '["No sexual dysfunction and no weight gain", "Highly sedating and prevents seizures", "Treats psychosis and anxiety", "None"]', 0, 'Often used as an adjunct to reverse SSRI sexual dysfunction. (First Aid)'),
    (v_topic_id, '161: Absolute contraindications to Bupropion?', '["Hypertension", "Seizure disorders and Eating disorders (Bulimia/Anorexia)", "Diabetes", "Asthma"]', 1, 'Lowers seizure threshold; electrolyte imbalance in eating disorders increases risk. (MGH Pocket)'),
    (v_topic_id, '162: Mirtazapine mechanism of action?', '["SSRI", "Alpha-2 antagonist (increases NE and 5HT release)", "MAOI", "TCA"]', 1, 'Also blocks 5HT2, 5HT3, and H1 receptors. (Kaplan & Sadock)'),
    (v_topic_id, '163: Primary side effects of Mirtazapine?', '["Insomnia and weight loss", "Sedation and weight gain", "Hypertension", "Sexual dysfunction"]', 1, 'Very useful in depressed elderly patients with insomnia and anorexia. (First Aid)'),
    (v_topic_id, '164: Trazodone is primarily used today for:', '["Primary depression", "Insomnia (at low doses)", "Mania", "Psychosis"]', 1, 'Too sedating at antidepressant doses. (MGH Pocket)'),
    (v_topic_id, '165: A rare but severe side effect of Trazodone (especially in young males) is:', '["Priapism", "Agranulocytosis", "Hepatitis", "Retinitis pigmentosa"]', 0, '"Trazobone". A urologic emergency. (First Aid)'),
    (v_topic_id, '166: Tricyclic Antidepressants (TCAs) have a narrow therapeutic index. Overdose causes death primarily via:', '["Liver failure", "Respiratory depression", "Cardiac arrhythmias (QTc prolongation, wide QRS)", "Renal failure"]', 2, 'Due to sodium channel blockade. (Kaplan & Sadock)'),
    (v_topic_id, '167: The treatment for TCA overdose with a widened QRS complex is:', '["Flumazenil", "Sodium Bicarbonate", "Physostigmine", "Naloxone"]', 1, 'Overcomes sodium channel blockade. (First Aid)'),
    (v_topic_id, '168: TCAs cause dry mouth, constipation, blurry vision, and urinary retention due to:', '["Antihistamine effects", "Anticholinergic (anti-muscarinic) effects", "Alpha-1 blockade", "Serotonin blockade"]', 1, 'Classic side effect profile. (MGH Pocket)'),
    (v_topic_id, '169: TCAs cause orthostatic hypotension due to:', '["Anti-muscarinic effects", "Alpha-1 adrenergic blockade", "Histamine blockade", "None"]', 1, 'Risk of falls in the elderly. (Kaplan & Sadock)'),
    (v_topic_id, '170: Which TCA is specifically FDA approved for OCD?', '["Amitriptyline", "Imipramine", "Clomipramine", "Nortriptyline"]', 2, 'Highly serotonergic TCA. (First Aid)'),
    (v_topic_id, '171: Imipramine was historically used to treat what condition in children?', '["ADHD", "Enuresis (bedwetting)", "Autism", "Tics"]', 1, 'Due to strong anticholinergic properties (contracts internal sphincter). (MGH Pocket)'),
    (v_topic_id, '172: Which TCA is considered safest in the elderly because it has the fewest anticholinergic side effects?', '["Amitriptyline", "Doxepin", "Nortriptyline", "Imipramine"]', 2, 'Secondary amine TCAs (Nortriptyline, Desipramine) are better tolerated. (Kaplan & Sadock)'),
    (v_topic_id, '173: Serotonin Syndrome is characterized by a triad of:', '["Autonomic instability, Altered mental status, Neuromuscular hyperactivity (clonus/hyperreflexia)", "Fever, rigidity, high CK", "Coma, miosis, respiratory depression", "None"]', 0, 'Hyperreflexia/clonus distinguishes it from NMS (rigidity). (First Aid)'),
    (v_topic_id, '174: Antidote for severe Serotonin Syndrome?', '["Dantrolene", "Cyproheptadine (5HT2 antagonist)", "Bromocriptine", "Benztropine"]', 1, 'Used if benzodiazepines and supportive care fail. (MGH Pocket)'),
    (v_topic_id, '175: MAOIs used for depression include Phenelzine, Tranylcypromine, and:', '["Selegiline", "Fluoxetine", "Bupropion", "Venlafaxine"]', 0, 'Selegiline patch (Emsam) at low doses does not require dietary restrictions. (Kaplan & Sadock)'),
    (v_topic_id, '176: Esketamine nasal spray is a novel treatment approved for:', '["Mild depression", "Treatment-resistant depression and suicidal ideation", "Mania", "OCD"]', 1, 'NMDA receptor antagonist; rapidly acting. (First Aid)'),
    (v_topic_id, '177: How long does it generally take for SSRIs to show their full antidepressant effect?', '["1 day", "1 week", "4-6 weeks", "6 months"]', 2, 'Requires receptor downregulation and neurogenesis. (MGH Pocket)'),
    (v_topic_id, '178: If a patient responds well to an SSRI for their first MDD episode, how long should they continue the medication before tapering?', '["Stop immediately", "1-2 months", "6-9 months after remission", "Lifelong"]', 2, 'Continuation therapy prevents relapse. (First Aid)'),
    (v_topic_id, '179: If a patient has had 3 or more severe episodes of MDD, how long should they be on an antidepressant?', '["6 months", "1 year", "Indefinitely / Lifelong", "Never"]', 2, 'Maintenance therapy is recommended for recurrent/severe disease. (Kaplan & Sadock)'),
    (v_topic_id, '180: The "SSRI Discontinuation Syndrome" presents with "brain zaps," flu-like symptoms, and dizziness. Which SSRI is most likely to cause this?', '["Fluoxetine", "Paroxetine", "Sertraline", "Citalopram"]', 1, 'Paroxetine has a short half-life and no active metabolites. (MGH Pocket)'),
    (v_topic_id, '181: Which SSRI is the only one FDA approved for Bulimia Nervosa?', '["Fluoxetine", "Sertraline", "Paroxetine", "Citalopram"]', 0, 'Dosed higher than for depression (e.g., 60mg). (First Aid)'),
    (v_topic_id, '182: A pregnant patient with MDD. Which SSRI is generally avoided due to a specific risk of cardiac defects (Ebstein/septal)?', '["Sertraline", "Paroxetine", "Fluoxetine", "Citalopram"]', 1, 'Category D. (Kaplan & Sadock)'),
    (v_topic_id, '183: What is the preferred SSRI for breastfeeding women?', '["Sertraline", "Fluoxetine", "Paroxetine", "Fluvoxamine"]', 0, 'Very low transfer into breast milk. (MGH Pocket)'),
    (v_topic_id, '184: Which herbal supplement acts essentially like a weak SSRI and can cause Serotonin Syndrome if combined with prescription antidepressants?', '["Ginkgo biloba", "St. John''s Wort", "Ginseng", "Valerian root"]', 1, 'Potent CYP inducer as well. (First Aid)'),
    (v_topic_id, '185: Normal therapeutic range for Lithium?', '["0.1 - 0.4", "0.6 - 1.2 mEq/L", "2.0 - 3.0", "10 - 20"]', 1, 'Toxicity usually begins > 1.5 mEq/L. (MGH Pocket)'),
    (v_topic_id, '186: Which baseline labs are required before starting Lithium?', '["BUN/Cr, TSH, Pregnancy test, ECG (if >40)", "LFTs, CBC", "Amylase, Lipase", "None"]', 0, 'Cleared by kidneys, affects thyroid, teratogenic, affects nodes. (First Aid)'),
    (v_topic_id, '187: Long-term renal side effect of Lithium?', '["Nephrotic syndrome", "Nephrogenic Diabetes Insipidus (polyuria/polydipsia) and CKD", "Renal cell carcinoma", "Stones"]', 1, 'Treated with Amiloride if Li cannot be stopped. (Kaplan & Sadock)'),
    (v_topic_id, '188: Long-term endocrine side effect of Lithium?', '["Hyperthyroidism", "Hypothyroidism", "Cushing''s", "Addison''s"]', 1, 'Check TSH every 6-12 months. Can treat with Levothyroxine while continuing Li. (MGH Pocket)'),
    (v_topic_id, '189: Baseline labs for starting Valproate (Depakote)?', '["BUN/Cr", "LFTs, CBC (platelets), Pregnancy test", "TSH", "ECG"]', 1, 'Risk of hepatotoxicity, thrombocytopenia, and neural tube defects. (First Aid)'),
    (v_topic_id, '190: Signs of severe Valproate toxicity?', '["Hyperreflexia", "Lethargy, coma, hyperammonemic encephalopathy", "Rigidity", "Arrhythmia"]', 1, 'Treated with L-carnitine. (Kaplan & Sadock)'),
    (v_topic_id, '191: Baseline testing for Carbamazepine?', '["BUN", "CBC (risk of aplastic anemia/agranulocytosis) and LFTs", "TSH", "Amylase"]', 1, 'Also causes SIADH (hyponatremia). (MGH Pocket)'),
    (v_topic_id, '192: Carbamazepine induces its own metabolism. This is called:', '["Autoinduction", "Inhibition", "Saturation", "None"]', 1, 'CYP3A4 autoinducer; half-life decreases after a few weeks. (First Aid)'),
    (v_topic_id, '193: Lurasidone must be taken with:', '["Empty stomach", "Food (at least 350 calories)", "Milk", "Grapefruit juice"]', 1, 'Absorption is drastically reduced without food. (MGH Pocket)'),
    (v_topic_id, '194: Ziprasidone must also be taken with:', '["Empty stomach", "Food (at least 500 calories)", "Nothing", "Water only"]', 1, 'Also known for QTc prolongation. (First Aid)'),
    (v_topic_id, '195: Which antipsychotic used in Bipolar Disorder has the highest risk for metabolic syndrome (weight gain, diabetes, lipids)?', '["Aripiprazole", "Olanzapine", "Ziprasidone", "Lurasidone"]', 1, 'Clozapine also has extreme metabolic risk. (Kaplan & Sadock)'),
    (v_topic_id, '196: Which antipsychotics are considered most "weight neutral"?', '["Olanzapine and Clozapine", "Aripiprazole, Ziprasidone, Lurasidone", "Quetiapine", "Risperidone"]', 1, 'Preferred in obese or diabetic patients. (MGH Pocket)'),
    (v_topic_id, '197: For a patient with MDD taking an SSRI who has partial response, what is a common augmentation strategy?', '["Add Bupropion, Lithium, or an atypical antipsychotic (Aripiprazole/Quetiapine)", "Add an MAOI", "Add another SSRI", "Stop all meds"]', 0, 'Evidence-based augmentation strategies. (First Aid)'),
    (v_topic_id, '198: A patient is profoundly depressed and refusing to eat or drink. Best next step?', '["Start SSRI and wait 4 weeks", "ECT (Electroconvulsive Therapy) for rapid response", "Psychotherapy", "Valproate"]', 1, 'ECT is indicated for depression with starvation, catatonia, or severe suicidality. (Kaplan & Sadock)'),
    (v_topic_id, '199: Transcranial Magnetic Stimulation (TMS) is approved for:', '["Bipolar mania", "Treatment-resistant MDD", "Schizophrenia", "OCD"]', 1, 'Non-invasive, no anesthesia required, unlike ECT. (MGH Pocket)'),
    (v_topic_id, '200: Vagus Nerve Stimulation (VNS) involves a pacemaker-like device and is used for:', '["Acute mania", "Chronic, severe, treatment-resistant MDD", "Panic attacks", "ADHD"]', 1, 'Surgically implanted. (First Aid)'),

    -- SECTION 6: Advanced Diagnostic Scenarios and Nuances (201-250)
    (v_topic_id, '201: A 70-year-old man presents with memory loss, poor concentration, and apathy. He frequently says "I don''t know" on the MMSE. Diagnosis to rule out?', '["Alzheimer''s", "Pseudodementia (MDD presenting as cognitive impairment)", "Delirium", "Normal aging"]', 1, 'Treating the depression restores cognitive function. (Kaplan & Sadock)'),
    (v_topic_id, '202: How does pseudodementia differ from true dementia regarding symptom onset?', '["Slow and insidious", "Relatively rapid onset, patient highlights their cognitive deficits", "Present since birth", "None"]', 1, 'Dementia patients often confabulate or hide deficits; depressed patients complain about them. (First Aid)'),
    (v_topic_id, '203: A patient has mood swings. For 3 days they feel highly energetic and productive, then return to normal. Diagnosis?', '["Bipolar II", "Normal mood fluctuation (Does not meet 4-day criteria for hypomania)", "Cyclothymia", "Bipolar I"]', 1, 'Must be at least 4 days for a formal hypomanic diagnosis. (DSM-5)'),
    (v_topic_id, '204: Can a diagnosis of MDD be made if the patient has a history of a single 5-day hypomanic episode?', '["Yes", "No, the diagnosis is Bipolar II", "No, the diagnosis is Bipolar I", "No, it''s Cyclothymia"]', 1, 'A history of ANY hypomanic episode rules out MDD and makes it Bipolar II. (DSM-5)'),
    (v_topic_id, '205: A teenager is moody, irritable, and sleeps 14 hours a day. He eats excessively and feels "heavy" in his limbs. Best treatment?', '["Fluoxetine (SSRI is first-line, even for atypical features)", "MAOI", "ECT", "Lithium"]', 0, 'Though MAOIs are classic for atypical, SSRIs are still the first-line choice due to safety. (MGH Pocket)'),
    (v_topic_id, '206: A patient with Bipolar I is stable on Lithium. They are prescribed hydrochlorothiazide for hypertension. What will happen to Lithium levels?', '["Decrease", "Increase (potential toxicity)", "Stay the same", "Flunctuate"]', 1, 'Thiazides decrease renal clearance of Lithium. (First Aid)'),
    (v_topic_id, '207: A 25-year-old female with Bipolar I wants to become pregnant. She is on Valproate. What is the recommendation?', '["Continue Valproate", "Switch to Lithium or an atypical antipsychotic (Lurasidone/Quetiapine)", "Switch to Carbamazepine", "Stop all meds immediately without taper"]', 1, 'Valproate is highly teratogenic. Atypicals are increasingly preferred in pregnancy. (Kaplan & Sadock)'),
    (v_topic_id, '208: Which phase of sleep is increased in MDD?', '["Stage 1", "Stage 2", "Slow Wave Sleep (Stage 3/4)", "REM sleep total duration"]', 3, 'REM sleep increases, REM latency decreases, and Slow Wave Sleep decreases. (MGH Pocket)'),
    (v_topic_id, '209: The dexamethasone suppression test in a healthy individual causes ____ of cortisol. In severe MDD, there is ____.', '["Suppression; Non-suppression", "Non-suppression; Suppression", "Increase; Decrease", "None"]', 0, 'HPA axis is hyperactive in MDD. (First Aid)'),
    (v_topic_id, '210: What is the most common psychiatric complication of stroke?', '["Mania", "Post-stroke depression", "Psychosis", "Panic disorder"]', 1, 'Occurs in up to 30-50% of stroke patients. (Kaplan & Sadock)'),
    (v_topic_id, '211: Patient with severe depression + auditory hallucinations telling him he is a sinner. Treatment?', '["SSRI", "Antipsychotic", "SSRI + Antipsychotic OR ECT", "CBT"]', 2, 'Psychotic depression requires combined pharmacology or ECT. (First Aid)'),
    (v_topic_id, '212: A 30-year-old man thinks he is Jesus Christ and has not slept in 8 days. He has no history of depression. Diagnosis?', '["Schizophrenia", "Bipolar I Disorder, current episode manic, with psychotic features", "Delusional disorder", "MDD"]', 1, 'Grandiose delusions + acute lack of sleep + no depression = Mania with psychosis. (DSM-5)'),
    (v_topic_id, '213: A patient has 2 years of constant hypomanic symptoms and mild depressive symptoms, but then has a full Manic episode. New diagnosis?', '["Cyclothymia", "Bipolar I Disorder", "Bipolar II Disorder", "Schizoaffective"]', 1, 'Any full manic episode upgrades the diagnosis to Bipolar I. (First Aid)'),
    (v_topic_id, '214: Which therapy focuses on identifying and altering cognitive distortions and negative automatic thoughts?', '["Psychoanalysis", "CBT (Cognitive Behavioral Therapy)", "DBT", "Supportive therapy"]', 1, 'Developed by Aaron Beck. (MGH Pocket)'),
    (v_topic_id, '215: "Dialectical Behavior Therapy" (DBT) is primarily used for which disorder (often comorbid with mood disorders)?', '["Schizophrenia", "Borderline Personality Disorder", "OCD", "ADHD"]', 1, 'Focuses on mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness. (Kaplan & Sadock)'),
    (v_topic_id, '216: How long must a patient be on an SSRI before deciding it is ineffective?', '["1 week", "4-6 weeks at a therapeutic dose", "12 weeks", "6 months"]', 1, 'If no response by 4-6 weeks, consider dose increase or switch. (First Aid)'),
    (v_topic_id, '217: A patient on Citalopram complains of delayed ejaculation. Management?', '["Stop the drug", "Lower dose, switch to non-SSRI (Bupropion/Mirtazapine), or add Bupropion/Sildenafil", "Tell them it will pass", "Switch to Paroxetine"]', 1, 'Common management for SSRI-induced sexual dysfunction. (MGH Pocket)'),
    (v_topic_id, '218: A depressed patient has severe anorexia and weight loss. Which antidepressant is a good choice to help with sleep and appetite?', '["Fluoxetine", "Bupropion", "Mirtazapine", "Venlafaxine"]', 2, 'Mirtazapine is an appetite stimulant and highly sedating. (First Aid)'),
    (v_topic_id, '219: A depressed patient wants to quit smoking. Which antidepressant is FDA approved for smoking cessation?', '["Sertraline", "Bupropion (Zyban)", "Mirtazapine", "Trazodone"]', 1, 'Also helpful for ADHD. (Kaplan & Sadock)'),
    (v_topic_id, '220: A patient with MDD complains of severe neuropathic pain from diabetes. Which antidepressant is dual-purpose here?', '["Escitalopram", "Duloxetine", "Bupropion", "Mirtazapine"]', 1, 'SNRI works for pain pathways. (First Aid)'),
    (v_topic_id, '221: Patient taking Phenelzine (MAOI) eats salami and cheese, presents with BP 220/120 and severe headache. Diagnosis?', '["Serotonin syndrome", "Hypertensive Crisis", "Migraine", "NMS"]', 1, 'Tyramine acts as a sympathomimetic. (MGH Pocket)'),
    (v_topic_id, '222: Serotonin syndrome vs NMS: Which has hyperreflexia and clonus?', '["NMS", "Serotonin Syndrome", "Both", "Neither"]', 1, 'NMS presents with lead-pipe rigidity and hyporeflexia. (First Aid)'),
    (v_topic_id, '223: First step in managing a patient expressing acute suicidal intent with a plan?', '["Prescribe SSRI", "Hospitalize (involuntarily if necessary)", "Call their family", "CBT"]', 1, 'Safety is the paramount priority. (Kaplan & Sadock)'),
    (v_topic_id, '224: A 19-year-old is started on Fluoxetine. What FDA black box warning applies to patients < 25 years old?', '["Liver failure", "Increased risk of suicidal thoughts/behaviors in the first few weeks", "Seizures", "Sudden cardiac death"]', 1, 'Must be monitored closely upon initiation. (First Aid)'),
    (v_topic_id, '225: A bipolar patient presents with a rash that is spreading and blistering on their mucous membranes after starting a new medication. Which medication?', '["Lithium", "Lamotrigine (Stevens-Johnson Syndrome)", "Valproate", "Quetiapine"]', 1, 'Medical emergency; stop drug immediately. (MGH Pocket)'),
    (v_topic_id, '226: What is "Rapid Cycling"?', '["Mood swings in one day", ">4 mood episodes per year", "Switching from mania to depression in a week", "None"]', 1, 'DSM-5 definition. (Kaplan & Sadock)'),
    (v_topic_id, '227: Can rapid cycling occur in Bipolar II?', '["Yes", "No", "Only in men", "Only in children"]', 0, 'Can occur in either Bipolar I or II. (DSM-5)'),
    (v_topic_id, '228: A patient with acute mania is highly agitated and aggressive in the ED. Best immediate treatment?', '["Lithium PO", "IM Haloperidol + IM Lorazepam", "CBT", "Valproate PO"]', 1, 'Chemical restraint/sedation is required for safety. (First Aid)'),
    (v_topic_id, '229: What is the risk of giving an SSRI to a patient with undiagnosed Bipolar Disorder who presents with depression?', '["Nothing", "Inducing a manic episode (Manic Switch)", "Serotonin syndrome", "Seizures"]', 1, 'Always screen for past hypomania/mania before prescribing an antidepressant. (MGH Pocket)'),
    (v_topic_id, '230: Which psychiatric disorder has the highest rate of completed suicide?', '["Schizophrenia", "Bipolar Disorder and MDD", "OCD", "Specific Phobia"]', 1, 'Mood disorders carry a ~15% lifetime mortality from suicide. (Kaplan & Sadock)'),
    (v_topic_id, '231: Which of the following is an environmental risk factor for MDD?', '["High socioeconomic status", "Adverse childhood experiences (trauma/abuse)", "Summer season", "Eating meat"]', 1, 'Early trauma permanently alters HPA axis stress reactivity. (First Aid)'),
    (v_topic_id, '232: In MDD, PET scans typically show ____ glucose metabolism in the prefrontal cortex.', '["Increased", "Decreased", "Normal", "Variable"]', 1, 'Hypofrontality is linked to apathy and poor concentration. (Kaplan & Sadock)'),
    (v_topic_id, '233: Does the severity of a patient''s first depressive episode predict the severity of future episodes?', '["Yes", "No", "Only in women", "Only in elderly"]', 0, 'Severe first episodes often predict a severe, recurrent course. (MGH Pocket)'),
    (v_topic_id, '234: What is the most common method of completed suicide in the United States?', '["Hanging", "Poisoning/Overdose", "Firearms", "Jumping"]', 2, 'Guns account for over 50% of completed suicides. (First Aid)'),
    (v_topic_id, '235: Women ____ suicide more often; Men ____ suicide more often.', '["Attempt; Complete", "Complete; Attempt", "Think about; Attempt", "None"]', 0, 'Men use more lethal means (guns vs. pills). (Kaplan & Sadock)'),
    (v_topic_id, '236: Bipolar Disorder is often misdiagnosed initially as:', '["Schizophrenia", "Major Depressive Disorder", "Panic Disorder", "PTSD"]', 1, 'Patients usually seek help only when depressed, hiding the hypomania. (MGH Pocket)'),
    (v_topic_id, '237: A patient has chronic, daily low mood for 3 years but no other symptoms. Does this meet criteria for PDD?', '["Yes", "No", "Depends on age", "Depends on gender"]', 1, 'Must have depressed mood PLUS at least 2 other symptoms. (DSM-5)'),
    (v_topic_id, '238: What differentiates Grief from a Major Depressive Episode?', '["Grief comes in ''waves'' (pangs of grief) mixed with positive memories", "Grief features constant pervasive anhedonia", "Grief always involves psychosis", "Grief lasts exactly 1 year"]', 0, 'MDD is pervasive; grief is wave-like. (First Aid)'),
    (v_topic_id, '239: If a grieving patient develops persistent thoughts of worthlessness, severe psychomotor retardation, and suicidal ideation, what is the diagnosis?', '["Normal grief", "Major Depressive Disorder", "Bipolar", "Adjustment disorder"]', 1, 'These are red flags that grief has transitioned into MDD. (Kaplan & Sadock)'),
    (v_topic_id, '240: Adjustment Disorder with Depressed Mood requires symptoms to start within ___ of the stressor and resolve within ___ of the stressor ending.', '["1 month; 3 months", "3 months; 6 months", "6 months; 1 year", "1 week; 1 month"]', 1, 'Symptoms must not meet full criteria for MDD. (DSM-5)'),
    (v_topic_id, '241: If a patient has full SIGECAPS for 3 weeks following a job loss, what is the diagnosis?', '["Adjustment disorder", "Major Depressive Disorder", "Normal reaction", "Brief psychotic disorder"]', 1, 'If full criteria for MDD are met, it is MDD, regardless of the trigger. (First Aid)'),
    (v_topic_id, '242: Which endocrine disorder is a classic medical mimic of mania?', '["Hypothyroidism", "Hyperthyroidism (Thyrotoxicosis)", "Addison''s disease", "Diabetes"]', 1, 'Always check TSH. (MGH Pocket)'),
    (v_topic_id, '243: A patient with Bipolar I on Lithium presents with polyuria and polydipsia. Blood test shows normal glucose. Diagnosis?', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus", "Central DI", "Psychogenic polydipsia"]', 1, 'Lithium blocks ADH response in the kidney. (Kaplan & Sadock)'),
    (v_topic_id, '244: Treatment for Lithium-induced NDI?', '["Stop Lithium, or add Amiloride", "Insulin", "Desmopressin (DDAVP)", "Fluid restriction"]', 0, 'Amiloride blocks Li entry into ENaC channels in the collecting duct. (First Aid)'),
    (v_topic_id, '245: Which cardiac defect is associated with Lithium exposure in utero?', '["Tetralogy of Fallot", "Ebstein''s Anomaly (downward displacement of tricuspid valve)", "VSD", "ASD"]', 1, 'Risk is ~1/1000, which is elevated but still relatively low. (MGH Pocket)'),
    (v_topic_id, '246: A depressed patient has an ECG showing a prolonged QTc interval. Which SSRI should specifically be avoided?', '["Sertraline", "Citalopram", "Fluoxetine", "Paroxetine"]', 1, 'Citalopram (and to a lesser extent escitalopram) prolong QTc. (First Aid)'),
    (v_topic_id, '247: What is the mechanism of action of Tranylcypromine?', '["SSRI", "SNRI", "Monoamine Oxidase Inhibitor (MAOI)", "TCA"]', 2, 'Irreversible inhibitor of MAO A and B. (Kaplan & Sadock)'),
    (v_topic_id, '248: Selegiline is a selective inhibitor of ____ at low doses.', '["MAO-A", "MAO-B", "Serotonin", "Dopamine"]', 1, 'Used in Parkinson''s disease; at high doses it loses selectivity. (MGH Pocket)'),
    (v_topic_id, '249: Which atypical antipsychotic is most associated with hyperprolactinemia (causing galactorrhea/amenorrhea)?', '["Quetiapine", "Risperidone (and Paliperidone)", "Aripiprazole", "Clozapine"]', 1, 'Due to strong D2 blockade in the tuberoinfundibular pathway. (First Aid)'),
    (v_topic_id, '250: What is the unique mechanism of Aripiprazole?', '["Full D2 antagonist", "Partial D2 agonist", "D4 antagonist", "5HT1A full agonist"]', 1, 'Acts as an antagonist in hyperdopaminergic states (mania/psychosis) and agonist in hypodopaminergic states. (Kaplan & Sadock)'),

    -- SECTION 7: Rapid Fire Review and Miscellaneous (251-320)
    (v_topic_id, '251: Most common side effect of ECT?', '["Seizures", "Amnesia (Retro/Anterograde)", "Death", "Fracture"]', 1, 'Short term memory loss is standard. (First Aid)'),
    (v_topic_id, '252: ECT absolute contraindication?', '["Pregnancy", "None", "Pacemaker", "Old age"]', 1, 'There are no absolute contraindications, though space-occupying brain lesions are high risk. (MGH Pocket)'),
    (v_topic_id, '253: TCA overdose ECG finding?', '["ST elevation", "Wide QRS", "Peaked T waves", "A-fib"]', 1, 'Due to fast sodium channel blockade. (First Aid)'),
    (v_topic_id, '254: SSRI with longest half-life?', '["Sertraline", "Fluoxetine", "Paroxetine", "Citalopram"]', 1, 'No need to taper. (Kaplan & Sadock)'),
    (v_topic_id, '255: SSRI with highest risk of withdrawal?', '["Paroxetine", "Fluoxetine", "Sertraline", "Escitalopram"]', 0, 'Shortest half-life. (MGH Pocket)'),
    (v_topic_id, '256: Best SSRI for a patient on multiple medications (fewest CYP interactions)?', '["Fluoxetine", "Escitalopram / Citalopram", "Paroxetine", "Fluvoxamine"]', 1, 'Cleanest metabolic profile. (First Aid)'),
    (v_topic_id, '257: SNRI used for fibromyalgia?', '["Venlafaxine", "Duloxetine", "Bupropion", "Mirtazapine"]', 1, 'Also neuropathic pain. (Kaplan & Sadock)'),
    (v_topic_id, '258: Antidepressant causing priapism?', '["Trazodone", "Mirtazapine", "Bupropion", "Sertraline"]', 0, 'Alpha blockade. (MGH Pocket)'),
    (v_topic_id, '259: Antidepressant causing weight gain and sedation (often used in elderly with insomnia/anorexia)?', '["Bupropion", "Mirtazapine", "Venlafaxine", "Fluoxetine"]', 1, 'Alpha-2 antagonist. (First Aid)'),
    (v_topic_id, '260: Antidepressant that lowers seizure threshold (avoid in bulimia)?', '["Sertraline", "Bupropion", "Trazodone", "Mirtazapine"]', 1, 'NDRI. (Kaplan & Sadock)'),
    (v_topic_id, '261: MAOI + Tyramine = ?', '["Serotonin syndrome", "Hypertensive crisis", "NMS", "Nothing"]', 1, 'Cheese reaction. (MGH Pocket)'),
    (v_topic_id, '262: SSRI + MAOI = ?', '["Serotonin syndrome", "Hypertensive crisis", "NMS", "Nothing"]', 0, 'Wait 2 weeks (5 weeks for fluoxetine) between them. (First Aid)'),
    (v_topic_id, '263: Lithium toxicity sign?', '["Rigidity", "Tremor, ataxia, vomiting", "Fever", "Constipation"]', 1, 'Cerebellar signs. (Kaplan & Sadock)'),
    (v_topic_id, '264: Valproate teratogen?', '["Ebstein''s", "Neural tube defects", "Cleft lip", "None"]', 1, 'Spina bifida. (MGH Pocket)'),
    (v_topic_id, '265: Lithium teratogen?', '["Neural tube", "Ebstein''s anomaly", "Phocomelia", "None"]', 1, 'Cardiac defect. (First Aid)'),
    (v_topic_id, '266: Lamotrigine severe rash?', '["Psoriasis", "Stevens-Johnson Syndrome", "Eczema", "None"]', 1, 'Taper slowly. (Kaplan & Sadock)'),
    (v_topic_id, '267: Carbamazepine blood dyscrasia?', '["Anemia", "Agranulocytosis / Aplastic anemia", "Thrombocytosis", "None"]', 1, 'Check CBC. (MGH Pocket)'),
    (v_topic_id, '268: Valproate liver issue?', '["Cirrhosis", "Fatal hepatotoxicity", "Gallstones", "None"]', 1, 'Check LFTs. (First Aid)'),
    (v_topic_id, '269: Lithium thyroid issue?', '["Hyperthyroid", "Hypothyroid", "Cancer", "None"]', 1, 'Check TSH. (Kaplan & Sadock)'),
    (v_topic_id, '270: Bipolar I requirement?', '["Depression", "Mania (1 episode)", "Psychosis", "None"]', 1, 'Only mania needed. (DSM-5)'),
    (v_topic_id, '271: Bipolar II requirement?', '["Mania", "Hypomania + MDD", "Cyclothymia", "None"]', 1, 'No mania ever. (DSM-5)'),
    (v_topic_id, '272: Cyclothymia duration?', '["1 year", "2 years (adults)", "6 months", "None"]', 1, 'Chronic mild fluctuations. (First Aid)'),
    (v_topic_id, '273: MDD duration?', '["1 week", "2 weeks", "4 weeks", "None"]', 1, 'Core criteria. (DSM-5)'),
    (v_topic_id, '274: Mania duration?', '["4 days", "1 week (or hospitalization)", "2 weeks", "None"]', 1, 'Core criteria. (DSM-5)'),
    (v_topic_id, '275: Hypomania duration?', '["4 days", "1 week", "2 weeks", "None"]', 0, 'No marked impairment. (DSM-5)'),
    (v_topic_id, '276: Dysthymia (PDD) duration adults?', '["1 year", "2 years", "6 months", "None"]', 1, 'Chronic. (DSM-5)'),
    (v_topic_id, '277: Dysthymia (PDD) duration kids?', '["1 year", "2 years", "6 months", "None"]', 0, 'Shorter for youth. (DSM-5)'),
    (v_topic_id, '278: DMDD onset?', '["Before age 10", "After 18", "Any time", "None"]', 0, 'Pediatric diagnosis. (DSM-5)'),
    (v_topic_id, '279: SAD (Seasonal) treatment?', '["ECT", "Light therapy", "Lithium", "None"]', 1, 'Winter depression. (First Aid)'),
    (v_topic_id, '280: Postpartum blues duration limit?', '["1 week", "2 weeks", "4 weeks", "None"]', 1, 'Reassurance only. (MGH Pocket)'),
    (v_topic_id, '281: Postpartum depression onset?', '["During pregnancy or within 4 weeks of delivery", "1 year later", "None", "None"]', 0, 'Peripartum onset specifier. (DSM-5)'),
    (v_topic_id, '282: Postpartum psychosis risk?', '["Low", "High (infanticide/suicide)", "Zero", "None"]', 1, 'Psychiatric emergency. (Kaplan & Sadock)'),
    (v_topic_id, '283: Rapid cycling count?', '["2", "4 or more episodes/year", "6", "None"]', 1, 'Specifier. (DSM-5)'),
    (v_topic_id, '284: Atypical depression features?', '["Insomnia", "Hypersomnia, Hyperphagia, Leaden paralysis", "Weight loss", "None"]', 1, 'Mood reactivity is key. (First Aid)'),
    (v_topic_id, '285: Melancholic features?', '["Mood reactivity", "Profound anhedonia, worse in morning", "Hunger", "None"]', 1, 'Lack of reactivity. (DSM-5)'),
    (v_topic_id, '286: Catatonia treatment?', '["SSRI", "Lorazepam or ECT", "Lithium", "None"]', 1, 'Benzos work fast. (MGH Pocket)'),
    (v_topic_id, '287: Best predictor of suicide?', '["Gender", "Previous attempt", "Age", "None"]', 1, 'Past behavior. (Kaplan & Sadock)'),
    (v_topic_id, '288: Highest suicide rate group?', '["Young men", "Elderly white men", "Teen girls", "None"]', 1, 'Demographics. (First Aid)'),
    (v_topic_id, '289: Schizoaffective vs Bipolar with psychosis?', '["Schizoaffective has psychosis WITHOUT mood symptoms for >2 weeks", "No difference", "None", "None"]', 0, 'Key timeline distinction. (DSM-5)'),
    (v_topic_id, '290: Pseudodementia treatment?', '["Donepezil", "Antidepressants", "Memantine", "None"]', 1, 'Treat the depression. (MGH Pocket)'),
    (v_topic_id, '291: Bereavement exclusion in DSM-5?', '["Exists", "Removed", "Changed to 1 year", "None"]', 1, 'Can diagnose MDD during grief. (First Aid)'),
    (v_topic_id, '292: Left frontal stroke = ?', '["Mania", "Depression", "Apathy", "None"]', 1, 'Vascular depression. (Kaplan & Sadock)'),
    (v_topic_id, '293: Right frontal stroke = ?', '["Depression", "Mania / Euphoria", "Anger", "None"]', 1, 'Secondary mania. (MGH Pocket)'),
    (v_topic_id, '294: Pancreatic cancer = ?', '["Depression mimic", "Mania mimic", "OCD mimic", "None"]', 0, 'Occult malignancy. (First Aid)'),
    (v_topic_id, '295: Hypothyroidism = ?', '["Mania mimic", "Depression mimic", "Anxiety mimic", "None"]', 1, 'Rule out with TSH. (Kaplan & Sadock)'),
    (v_topic_id, '296: Hyperthyroidism = ?', '["Mania/Anxiety mimic", "Depression mimic", "None", "None"]', 0, 'Thyrotoxicosis. (MGH Pocket)'),
    (v_topic_id, '297: Stimulant intoxication = ?', '["Mania mimic", "Depression mimic", "None", "None"]', 0, 'Cocaine/Meth. (First Aid)'),
    (v_topic_id, '298: Stimulant withdrawal = ?', '["Mania mimic", "Depression mimic (crash)", "None", "None"]', 1, 'Hypersomnia/Dysphoria. (Kaplan & Sadock)'),
    (v_topic_id, '299: Steroids = ?', '["Steroid psychosis/mania", "Nothing", "None", "None"]', 0, 'Iatrogenic. (MGH Pocket)'),
    (v_topic_id, '300: Lurasidone = ?', '["Empty stomach", "Needs 350 calories", "None", "None"]', 1, 'Absorption requirement. (First Aid)'),
    (v_topic_id, '301: Ziprasidone = ?', '["Needs 500 calories", "Empty stomach", "None", "None"]', 0, 'Absorption requirement. (Kaplan & Sadock)'),
    (v_topic_id, '302: Clozapine/Olanzapine = ?', '["Weight neutral", "Highest weight gain / Metabolic risk", "None", "None"]', 1, 'Monitor A1c. (MGH Pocket)'),
    (v_topic_id, '303: Quetiapine = ?', '["Approved for bipolar depression", "Not used", "None", "None"]', 0, 'Highly sedating. (First Aid)'),
    (v_topic_id, '304: Aripiprazole = ?', '["Partial agonist D2", "Full antagonist", "None", "None"]', 0, 'Weight neutral. (Kaplan & Sadock)'),
    (v_topic_id, '305: Venlafaxine = ?', '["Monitor BP (HTN risk)", "Monitor LFTs", "None", "None"]', 0, 'NE effect. (MGH Pocket)'),
    (v_topic_id, '306: Cyproheptadine = ?', '["NMS antidote", "Serotonin syndrome antidote", "None", "None"]', 1, '5HT2 block. (First Aid)'),
    (v_topic_id, '307: Dantrolene = ?', '["Serotonin syndrome", "NMS antidote / Malignant hyperthermia", "None", "None"]', 1, 'Muscle relaxant. (Kaplan & Sadock)'),
    (v_topic_id, '308: Flumazenil = ?', '["TCA antidote", "Benzo antidote", "Opioid antidote", "None"]', 1, 'GABA antagonist. (MGH Pocket)'),
    (v_topic_id, '309: Naloxone = ?', '["Benzo antidote", "Opioid antidote", "TCA antidote", "None"]', 1, 'Mu antagonist. (First Aid)'),
    (v_topic_id, '310: Sodium Bicarbonate = ?', '["TCA antidote (cardiac)", "Benzo antidote", "None", "None"]', 0, 'Alkalinizes serum. (Kaplan & Sadock)'),
    (v_topic_id, '311: Phentolamine = ?', '["MAOI hypertensive crisis antidote", "NMS", "None", "None"]', 0, 'Alpha blocker. (MGH Pocket)'),
    (v_topic_id, '312: REM latency in MDD?', '["Increased", "Decreased", "Normal", "None"]', 1, 'Enter REM faster. (First Aid)'),
    (v_topic_id, '313: Slow wave sleep in MDD?', '["Increased", "Decreased", "Normal", "None"]', 1, 'Less deep sleep. (Kaplan & Sadock)'),
    (v_topic_id, '314: Double depression?', '["MDD + Bipolar", "MDD + PDD (Dysthymia)", "None", "None"]', 1, 'Superimposed episodes. (DSM-5)'),
    (v_topic_id, '315: Mixed features specifier?', '["High suicide risk", "Low risk", "None", "None"]', 0, 'Dysphoric mania. (MGH Pocket)'),
    (v_topic_id, '316: Anxious distress specifier?', '["Poorer prognosis/treatment response", "Better prognosis", "None", "None"]', 0, 'Harder to treat. (First Aid)'),
    (v_topic_id, '317: Interpersonal Therapy (IPT)?', '["Focus on roles/transitions/grief", "Focus on childhood", "None", "None"]', 0, 'Time-limited. (Kaplan & Sadock)'),
    (v_topic_id, '318: CBT?', '["Focus on cognitive triad (self/world/future)", "Focus on diet", "None", "None"]', 0, 'Beck''s triad. (MGH Pocket)'),
    (v_topic_id, '319: Amiloride?', '["Treats Lithium-induced tremor", "Treats Lithium-induced NDI", "None", "None"]', 1, 'Blocks ENaC. (First Aid)'),
    (v_topic_id, '320: Final Pearl: Euthymia = ?', '["Normal mood (The Goal!)", "Mania", "Depression", "None"]', 0, 'The ultimate objective. (MediHelp Mastery)');

END $$;

COMMIT;
